export const money=(n:number)=>'$'+(Math.round(n*100)/100).toLocaleString('en-US',{maximumFractionDigits:2});
export const netWorth=(p:Player)=>p.cash+p.portfolio+p.business-p.debt;
export const chapterFor=(level:number)=>chapters[Math.min(9,Math.floor((level-1)/10))];
export function newPlayer(id:string,name:string,dream:Dream,careerId='hospitality-0'):Player{return{id,name,dream,level:1,cash:40,portfolio:0,business:0,passive:0,skill:0,health:80,debt:0,freedom:10,turns:0,decided:false,log:[],careerId,businessType:'',interests:{[findCareer(careerId).industry]:3},lastKind:'',trust:50,network:0,obligation:0,leaps:0,usedLeaps:0,streak:0,completed:0,checkpoint:{level:1,worth:40,portfolio:0,skill:0,freedom:10}};}
export function dreamGoals(p:Player){const d=dreams[p.dream];const base=[{label:'Net worth',current:netWorth(p),target:d.target,money:true},{label:'Free time',current:p.freedom,target:d.freedom,money:false},{label:'Wellbeing',current:p.health,target:p.dream==='athlete'?70:50,money:false}];
 const special=p.dream==='athlete'?[{label:'Competition wins',current:p.performances||0,target:6,money:false},{label:'Athletic skill',current:p.skill,target:85,money:false}]:p.dream==='artist'?[{label:'Fans',current:p.audience||0,target:3000,money:false},{label:'Headline shows',current:p.performances||0,target:4,money:false}]:p.dream==='explorer'?[{label:'Discoveries',current:p.discoveries||0,target:8,money:false}]:p.dream==='changemaker'?[{label:'Community impact',current:p.impact||0,target:300,money:false},{label:'Public trust',current:p.trust??50,target:75,money:false}]:[{label:p.dream==='freedom'?'Passive income / turn':'Business assets',current:p.dream==='freedom'?p.passive:p.business,target:p.dream==='freedom'?d.passive:d.asset,money:true},...(p.dream==='hotel'?[{label:'Own a hotel or B&B',current:/hotel|breakfast/i.test(p.businessType)?1:0,target:1,money:false}]:[])];return [base[0],...special,...base.slice(1)];}
export function levelGoal(level:number,p:Player){
 if(level===100){const gs=dreamGoals(p);return {label:'Complete your life dream',current:Math.floor(gs.reduce((n,g)=>n+Math.min(1,Math.max(0,g.current/g.target)),0)/gs.length*100),target:100,money:false,done:gs.every(g=>g.current>=g.target)};}
 const s=chapterFor(level).scale,i=p.checkpoint?.level===level&&p.checkpoint.kind!==undefined?p.checkpoint.kind:goalKind(p,level),b=p.checkpoint?.level===level?p.checkpoint:{worth:netWorth(p),portfolio:p.portfolio,skill:p.skill,freedom:p.freedom};
 const goals=[{label:'Earn new net worth this checkpoint',current:Math.max(0,netWorth(p)-b.worth),target:35*s,money:true},{label:'Grow your investments',current:Math.max(0,p.portfolio-b.portfolio),target:20*s,money:true},{label:'Build your skills',current:p.skill,target:Math.min(100,b.skill+7),money:false},{label:'Protect your wellbeing',current:p.health,target:78,money:false},{label:'Reclaim your time',current:p.freedom,target:Math.min(100,b.freedom+9),money:false}];
 const g=goals[i];return {...g,done:g.current>=g.target&&p.health>=25};
}
export function checkpoint(p:Player){p.checkpoint={kind:goalKind(p,p.level),level:p.level,worth:netWorth(p),portfolio:p.portfolio,skill:p.skill,freedom:p.freedom};}
