function hash(seed:number,level:number,turn:number){let v=(seed+level*374761393+turn*668265263)|0;v=Math.imul(v^(v>>>13),1274126177);return ((v^(v>>>16))>>>0)/4294967296;}
export function businessModel(name:string){if(/hotel|breakfast|rental/i.test(name))return 'hotel';if(/bakery|restaurant|truck|farm|coffee/i.test(name))return 'production';if(/store|brand|toy|manufacturing|furniture/i.test(name))return 'retail';if(/software|game|animation|media|course/i.test(name))return 'digital';return 'service';}
