 return labels[op.model].map((title,i)=>({title,hint:[`Costs ${money(12*s)} · demand +20${op.model==='production'?' · inventory +25':''} · wellbeing −3`,`Costs ${money(20*s)} · ${op.model==='production'||op.model==='retail'?'inventory +40':'capacity +25'} · recurring costs rise`,`Costs ${money(10*s)} · quality +20${op.model==='production'?' · demand +15':''} · free time +6`][i],cash:-(i===1?20:i===0?12:10)*s,health:i===0?-3:0,freedom:i===2?6:0,operationAction:['demand','capacity','quality'][i],kind:'operations',slot:'opportunity',outcome:`You changed how your ${p.businessType.toLowerCase()} operates.`,advice:op.model==='hotel'?`Room demand is ${op.demand}%, staffing ${op.staff}%. Promotions without staff create unhappy guests.`:op.model==='production'?`Inventory is ${op.stock} units. Unsold production spoils; demand is ${op.demand}.`:`Demand ${op.demand}, capacity ${op.staff}, quality ${op.quality}. Growth without capacity harms reputation.`}));
