 if(slot==='growth'){if(goal.label==='Grow your investments'&&c.kind==='invest')score+=115;if(goal.label==='Build your skills'&&c.kind==='learn')score+=100;if(goal.label==='Reclaim your time'&&c.kind==='automate')score+=100;}
