 if(p.level===100){if(c.kind==='dream')score+=160;if(c.kind==='dream-train'&&p.skill<85)score+=100;if(c.kind==='automate'&&(p.passive<dreams[p.dream].passive||p.freedom<dreams[p.dream].freedom))score+=180;if(c.kind==='business'&&((dreams[p.dream].asset>0&&p.business<dreams[p.dream].asset)||(p.dream==='hotel'&&!/hotel|breakfast/i.test(p.businessType)&&c.industry==='hospitality')))score+=200;}
 if(c.kind==='debt'&&((p.obligation||0)>10||p.debt>p.cash))score+=90;
 if(p.cash+(c.cash||0)<0||p.skill<(c.requiredSkill||0)||p.health<(c.requiredHealth||0))score-=1000;
