export function awardBonus(p:Player,roll:number){if(!Number.isInteger(roll)||roll<0||roll>999)throw new Error('Invalid bonus roll');if(roll!==0)return false;p.bonusCount=(p.bonusCount||0)+1;p.leaps=(p.leaps||0)+1;p.ownedAccessories=[...new Set([...(p.ownedAccessories||[]),'comet'])];return true;}
export function matchScore(p:Player){const goals=dreamGoals(p);return p.level+goals.reduce((n,g)=>n+Math.min(1,Math.max(0,g.current/g.target)),0)/Math.max(1,goals.length)*.2;}
