 outcome+=operate(p,g.seed);
 if(p.cash<0){p.debt+=-p.cash;outcome+=` A cash shortage added ${money(-p.cash)} debt.`;p.cash=0;}p.cash=Math.round(p.cash*100)/100;
 if(p.level>=21&&p.scholarship&&p.skill>=25){p.cash+=3000;p.scholarship=false;outcome+=' Your childhood preparation paid off: scholarship grant +$3,000.';}
 if((p.network||0)>=24&&(p.trust||0)>=65&&p.turns%5===0){p.cash+=25*s;p.network=Math.max(0,(p.network||0)-12);outcome+=` Your reliable reputation brought a referral worth ${money(25*s)}.`;}
 if(p.turns%8===0&&(p.obligation||0)>5){p.health=clamp(p.health-8);outcome+=' Unfinished commitments caused a stressful deadline: wellbeing −8.';}
 outcome+=` Earned ${money(income+p.passive)}; costs ${money(expenses)}${interest?', interest '+money(interest):''}.`;
 const goal=levelGoal(p.level,p);if(g.mode==='quick'){p.level=g.rulesVersion==='1.0'?quickLevel(p.turns):Math.min(100,1+p.turns*9);p.decided=false;checkpoint(p);}if(g.mode!=='quick'&&goal.done){if(p.level===100){g.winner=p.id;outcome+=' Your dream is complete!';}else{p.completed=(p.completed||0)+1;p.streak=(p.streak||0)+1;p.level++;p.decided=false;if((p.completed||0)%5===0){p.leaps=(p.leaps||0)+1;outcome+=' Earned a Leap Ticket: jump 3 levels on your next turn.';}checkpoint(p);outcome+=` Checkpoint ${oldLevel} cleared.`;}}
