 if(p.dream==='athlete')return [{...common,title:kid?'Enter a supervised school tournament':`Compete in a ${p.sport||'basketball'} championship`,hint:`Costs ${money(15*s)} · skill 30 & wellbeing 60 required · win +1 · wellbeing −12`,cash:-15*s,requiredSkill:30,requiredHealth:60,performances:1,health:-12,trust:3,outcome:'Preparation earned a competition win. Recovery is part of the next training cycle.',advice:'Competition needs 30 skill and 60 wellbeing. Wins are earned through preparation in this simplified sports story.'},{title:kid?'Join the school training squad':'Train with a specialist coach',slot:'growth',kind:'dream-train',cash:-4*s,skill:10,health:4,hint:`Costs ${money(4*s)} · skill +10 · wellbeing +4`,outcome:'You practiced technique instead of chasing a shortcut.',advice:'Consistent skill and recovery unlock competition.'}];
