 if(p.dream==='explorer')return [{...common,title:kid?'Join a supervised nature expedition':'Lead a responsible discovery expedition',cash:-20*s,requiredSkill:25,requiredHealth:55,discoveries:1,health:-7,freedom:3,hint:`Costs ${money(20*s)} · skill 25 & wellbeing 55 required · discovery +1`,outcome:'You documented a new place respectfully and returned with a discovery.',advice:'Budget for a safe return, respect local communities, and prepare before setting out.'},{title:'Study navigation and local history',slot:'growth',kind:'dream-train',skill:8,freedom:6,health:2,hint:'No cost · skills +8 · time +6',outcome:'Preparation made the next journey more independent.',advice:'Knowledge can create freedom without a big purchase.'}];
 if(p.dream==='changemaker')return [{...common,title:kid?'Lead a school community project':'Fund a neighborhood-led improvement',cash:-15*s,impact:35,trust:5,health:-4,hint:`Costs ${money(15*s)} · impact +35 · trust +5 · wellbeing −4`,outcome:'Residents chose the priority and shared ownership of the result.',advice:'Ask the people affected what they need before choosing the solution.'},{title:'Organize a listening circle',slot:'growth',kind:'dream-train',skill:6,trust:6,impact:8,hint:'Skills +6 · trust +6 · impact +8',outcome:'Listening built the foundation for useful work.',advice:'Trust and practical outcomes matter more than a photo opportunity.'}];return [];
