export function manageBusiness(game:Game,id:string,setting:unknown,roll=1){const p=game.players[game.turn];if(!p||p.id!==id)throw new Error('It is not your turn.');return applyChoice(game,id,0,p.decided?'prepare':'choice',roll,managementChoice(p,setting,chapterFor(p.level).scale));}
